DECLARE policy_id bigint; trial_config jsonb; trial_plan uuid;
BEGIN
 IF NEW.service_status<>'trial' THEN RETURN NEW; END IF;
 SELECT id,config->'trial' INTO policy_id,trial_config FROM public.billing_policy_versions ORDER BY id DESC LIMIT 1;
 IF NEW.trial_ends_at IS NULL THEN NEW.trial_ends_at=now()+make_interval(days=>(trial_config->>'durationDays')::integer); END IF;
 IF NEW.plan_version_id='00000000-0000-4000-8000-000000000052'::uuid THEN
  INSERT INTO public.subscription_plan_versions(code,version,name,seat_limit,job_limit)
  VALUES('configured_trial',policy_id::integer,'平台配置试用版',(trial_config->>'seatLimit')::integer,(trial_config->>'jobLimit')::integer)
  ON CONFLICT(code,version) DO NOTHING;
  SELECT id INTO trial_plan FROM public.subscription_plan_versions WHERE code='configured_trial' AND version=policy_id::integer;
  NEW.plan_version_id=trial_plan;
 END IF;
 RETURN NEW;
END;

DECLARE
  interview_status text;
BEGIN
  SELECT status
    INTO interview_status
    FROM interviews
   WHERE id = NEW.interview_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INTERVIEW_NOT_FOUND';
  END IF;

  IF interview_status = 'completed' THEN
    RAISE EXCEPTION 'INTERVIEW_ALREADY_COMPLETED';
  ELSIF interview_status = 'cancelled' THEN
    RAISE EXCEPTION 'INTERVIEW_CANCELLED';
  ELSIF interview_status <> 'scheduled' THEN
    RAISE EXCEPTION 'INTERVIEW_NOT_SCHEDULED';
  END IF;

  RETURN NEW;
END;

DECLARE row_data jsonb; org uuid; parent_table text; parent_key text; candidates jsonb[];
BEGIN
  IF TG_TABLE_SCHEMA<>'public' THEN
    IF TG_OP='TRUNCATE' THEN RETURN NULL; END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_OP='TRUNCATE' THEN
    IF EXISTS(SELECT 1 FROM recovery_control.company_data_cutovers) THEN RAISE EXCEPTION 'LEGACY_SNAPSHOT_READ_ONLY'; END IF;
    RETURN NULL;
  END IF;
  -- Shared department metadata remains editable; only ownership/deletion can change the scoped legacy selection.
  IF TG_TABLE_NAME='departments' THEN
    IF TG_OP='INSERT' THEN RETURN NEW; END IF;
    IF TG_OP='UPDATE' AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP='INSERT' THEN candidates:=ARRAY[to_jsonb(NEW)];
  ELSIF TG_OP='DELETE' THEN candidates:=ARRAY[to_jsonb(OLD)];
  ELSE candidates:=ARRAY[to_jsonb(OLD),to_jsonb(NEW)]; END IF;
  FOREACH row_data IN ARRAY candidates LOOP
    org:=NULL;
    IF row_data ? 'organization_id' THEN org:=(row_data->>'organization_id')::uuid;
    ELSE
      CASE TG_TABLE_NAME
        WHEN 'ai_resume_scoring_skill_jobs' THEN parent_table:='jobs'; parent_key:='job_id';
        WHEN 'department_approval_policies' THEN parent_table:='departments'; parent_key:='department_id';
        WHEN 'interview_question_preparations' THEN parent_table:='interviews'; parent_key:='interview_id';
        WHEN 'interview_audio_recordings','interview_audio_transcription_jobs','interview_transcript_versions','interview_transcript_postprocess_jobs'
          THEN parent_table:='interview_live_sessions'; parent_key:='session_id';
        ELSE RAISE EXCEPTION 'LEGACY_OWNERSHIP_UNKNOWN';
      END CASE;
      EXECUTE format('SELECT organization_id FROM public.%I WHERE id=$1',parent_table) INTO org USING (row_data->>parent_key)::uuid;
    END IF;
    IF EXISTS(SELECT 1 FROM recovery_control.company_data_cutovers WHERE organization_id=org) THEN
      RAISE EXCEPTION 'LEGACY_SNAPSHOT_READ_ONLY';
    END IF;
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;

DECLARE
  object_kind text;
  object_key text;
  object_schema text;
  object_parent uuid;
  object_organization uuid;
  intent public.object_write_intents%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME='resumes' THEN
    object_kind := 'resume';
    object_key := NEW.storage_key;
    object_parent := NEW.candidate_id;
    object_schema := TG_TABLE_SCHEMA;
    object_organization := NEW.organization_id;
  ELSIF TG_TABLE_NAME='interview_stored_objects' AND TG_TABLE_SCHEMA='public' THEN
    object_kind := 'interview';
    object_key := COALESCE(NEW.physical_key,NEW.storage_key);
    object_parent := NEW.session_id;
    object_schema := NEW.schema_name;
    object_organization := NEW.organization_id;
  ELSIF TG_TABLE_NAME='interview_audio_recordings' THEN
    object_kind := 'interview';
    object_parent := NEW.session_id;
    object_schema := TG_TABLE_SCHEMA;
    EXECUTE format('SELECT i.organization_id FROM %I.interview_live_sessions s JOIN %I.interviews i ON i.id=s.interview_id WHERE s.id=$1',object_schema,object_schema)
      INTO object_organization USING object_parent;
    IF object_organization IS NULL THEN
      RAISE EXCEPTION 'OBJECT_REFERENCE_OWNER_MISSING' USING ERRCODE='23514';
    END IF;
    SELECT COALESCE(o.physical_key,o.storage_key) INTO object_key
      FROM public.interview_stored_objects o
     WHERE o.organization_id=object_organization AND o.schema_name=object_schema
       AND o.session_id=object_parent AND o.storage_key=NEW.object_key;
    object_key := COALESCE(object_key,NEW.object_key);
  ELSE
    RAISE EXCEPTION 'OBJECT_REFERENCE_TABLE_UNSUPPORTED' USING ERRCODE='23514';
  END IF;
  IF object_key IS NULL THEN RETURN NEW; END IF;
  IF object_organization IS NULL OR (object_schema<>'public' AND object_schema<>'company_' || replace(object_organization::text,'-','')) THEN
    RAISE EXCEPTION 'OBJECT_REFERENCE_SCHEMA_MISMATCH' USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(object_kind || '-object:' || object_key,0));
  IF EXISTS (SELECT 1 FROM public.object_deletion_fences WHERE storage_kind=object_kind AND storage_key=object_key) THEN
    RAISE EXCEPTION 'OBJECT_REFERENCE_DELETION_FENCED' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.stored_object_locations WHERE storage_kind=object_kind AND storage_key=object_key AND organization_id<>object_organization) THEN
    RAISE EXCEPTION 'OBJECT_REFERENCE_OWNER_MISMATCH' USING ERRCODE='23514';
  END IF;
  SELECT * INTO intent FROM public.object_write_intents WHERE storage_key=object_key;
  IF FOUND AND (intent.status<>'bound' OR intent.organization_id<>object_organization
      OR intent.schema_name<>object_schema OR intent.storage_kind<>object_kind OR intent.parent_id<>object_parent) THEN
    RAISE EXCEPTION 'OBJECT_REFERENCE_INTENT_MISMATCH' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;

